"""Useful EN/FR search construction and device setup, checked 2 Nov 2026."""
UPDATED = '2026-11-02'
SLUGS = {
    'builder': {'en': '/vinted-search-builder', 'fr': '/fr/creer-recherche-vinted'},
    'phone': {'en': '/vinted-alerts-on-your-phone', 'fr': '/fr/alertes-vinted-telephone'},
}


def builder(lang):
    fr = lang == 'fr'
    form = '''<form class="search-builder" data-search-builder hidden novalidate>
<p id="builder-help">%s</p><div class="builder-fields">
<label for="builder-words">%s</label><input id="builder-words" name="words" type="text" maxlength="80" required aria-describedby="builder-help builder-error" placeholder="Nike Dunk Low">
<label for="builder-site">%s</label><select id="builder-site" name="site"></select>
<label for="builder-min">%s (<span data-builder-currency>EUR</span>)</label><input id="builder-min" name="min" type="text" inputmode="decimal" maxlength="10" aria-describedby="builder-help builder-error">
<label for="builder-max">%s (<span data-builder-currency>EUR</span>)</label><input id="builder-max" name="max" type="text" inputmode="decimal" maxlength="10" aria-describedby="builder-help builder-error"></div>
<button class="ct-btn" type="submit">%s</button><p id="builder-error" data-builder-error role="alert"></p>
<div data-builder-result hidden><label for="builder-url">%s</label><textarea id="builder-url" data-builder-url readonly rows="4"></textarea>
<div class="ct-actions"><button class="ct-btn ct-ghost" data-builder-copy type="button">%s</button><a class="ct-btn ct-ghost" data-builder-open target="_blank" rel="noopener noreferrer">%s</a><a class="ct-btn" data-builder-monitor>%s</a></div></div>
<p data-builder-message role="status"></p></form><noscript><p>%s</p></noscript>
<script src="/assets/search-contract.js" defer></script><script src="/assets/search-builder.js" defer></script>''' % (
        'Choisis le marché où tu peux acheter. Les prix sont dans sa devise, sans conversion. Laisse les prix vides pour ne pas imposer de limite ; minimum inférieur au maximum. Un point ou une virgule décimale est accepté.' if fr else
        'Choose the marketplace where you can buy. Prices use its currency, without conversion. Leave prices blank for no bound; a minimum must be below the maximum. Decimal points and commas are accepted.',
        'Mots de recherche' if fr else 'Search words', 'Marché Vinted' if fr else 'Vinted marketplace',
        'Prix minimum facultatif' if fr else 'Optional minimum price', 'Prix maximum facultatif' if fr else 'Optional maximum price',
        'Créer le lien' if fr else 'Build search link', 'Ton lien de recherche' if fr else 'Your search link',
        'Copier' if fr else 'Copy link', 'Ouvrir Vinted' if fr else 'Open Vinted', 'Préparer ma recherche SNYPD' if fr else 'Prepare my SNYPD hunt',
        'Active JavaScript pour générer le lien. Tu peux aussi chercher directement sur Vinted et copier l’adresse de la page de résultats.' if fr else
        'Enable JavaScript to build a link. You can also search directly on Vinted and copy the results-page address.')
    if not fr:
        title = 'Vinted Search Link Builder: Country, Keywords & Budget | SNYPD'
        desc = 'Build a Vinted search link with a supported marketplace, keywords and optional price range. Open or copy it free, then review a prefilled SNYPD hunt.'
        h1 = 'Build a Vinted search link'
        lead = 'Choose your marketplace and budget, then open or copy a reusable catalogue link. The tool works without a SNYPD account.'
        sections = [
            ('builder', 'Create your search', form),
            ('example', 'A specific search starts with a specific budget', '<p>For example, choose Belgium, type Nike Dunk Low and set a maximum of 23 EUR. The generated link searches vinted.be for those words and sorts new listings first. It does not certify the model, condition, authenticity or future resale price.</p><p>The optional minimum remains blank unless you enter one. Changing the marketplace clears both prices so a budget in euros cannot silently become pounds or zloty. Check the displayed currency before generating another link.</p>'),
            ('filters', 'Add sizes, condition and brand filters on Vinted', '<p>This builder sets words, optional prices and newest-first ordering. To filter an exact size, condition, category or brand, open the results on Vinted and use its own controls. Copy that final results address if you want SNYPD to monitor the more detailed search. We do not guess filter IDs.</p><p>A syntactically valid link does not guarantee matching stock, your account’s ability to purchase there, shipping availability or that Vinted will always keep the same URL format. Open and review the results before using it.</p>'),
            ('monitor', 'Review the search in SNYPD before saving', '<p>“Prepare my SNYPD hunt” passes the selected marketplace, words and exact price bounds to signup or login. On the same browser, the first-hunt form can prefill those values for review. It does not create or activate a hunt until you save it. Signup and the dashboard are available in English or French.</p><p>The optional prefill is kept locally for up to one day as part of the search you requested. Private browsing, cleared storage or switching browser/device can lose it. In that case copy the generated URL, sign in, open Filters and paste it; review its currency and bounds before saving.</p>'),
            ('privacy', 'What happens to the words you enter?', '<p>Generating a link happens in your browser. The tool does not send the typed words or prices as custom analytics events. Copying needs your device’s clipboard permission; if unavailable, the link is selected for manual copying. Opening Vinted or following the signup link sends the selected search in that destination’s address, as requested by you.</p><p>To calculate an item-price ceiling first, use the <a href="/vinted-profit-calculator">profit calculator</a>. See the <a href="/how-to-resell-on-vinted">reselling workflow</a>, <a href="/vinted-saved-searches">saved-search guide</a> and <a href="/vinted-alerts-on-your-phone">phone-alert setup</a> for the next steps.</p>'),
        ]
    else:
        title = 'Créer un lien de recherche Vinted : pays, mots et budget | SNYPD'
        desc = 'Crée un lien de recherche Vinted avec pays, mots-clés et prix facultatifs. Copie ou ouvre le lien gratuitement, puis prépare une recherche SNYPD à vérifier.'
        h1 = 'Crée ton lien de recherche Vinted'
        lead = 'Choisis ton marché et ton budget, puis ouvre ou copie un lien réutilisable. Aucun compte SNYPD n’est nécessaire pour le générer.'
        sections = [
            ('builder', 'Prépare ta recherche', form),
            ('exemple', 'Pars d’un modèle et d’un budget précis', '<p>Exemple fictif : sélectionne la Belgique, saisis Nike Dunk Low et fixe un maximum de 23 EUR. Le lien cherche ces mots sur vinted.be et classe les nouvelles annonces en premier. Il ne certifie ni le modèle, ni l’état, ni l’authenticité, ni un futur prix de revente.</p><p>Aucun prix minimum n’est imposé si tu n’en saisis pas. Changer de marché efface les deux prix pour éviter de transformer silencieusement un budget en euros en livres ou en zlotys. Vérifie la devise affichée avant de générer un nouveau lien.</p>'),
            ('filtres', 'Ajoute tailles, état et marques sur Vinted', '<p>L’outil définit les mots, les prix facultatifs et le tri par nouveautés. Pour une taille, un état, une catégorie ou une marque précise, ouvre les résultats sur Vinted et utilise ses filtres. Copie ensuite l’adresse finale si tu souhaites surveiller cette recherche détaillée avec SNYPD. Nous n’inventons pas d’identifiants de filtres.</p><p>Un lien correctement formé ne garantit pas des résultats, la possibilité d’acheter avec ton compte, la livraison ou la stabilité future du format Vinted. Ouvre et vérifie les résultats avant de t’en servir.</p>'),
            ('surveiller', 'Vérifie la recherche dans SNYPD avant de l’enregistrer', '<p>« Préparer ma recherche SNYPD » transmet le marché, les mots et les prix exacts à l’inscription ou à la connexion. Dans le même navigateur, le formulaire de première recherche peut les préremplir pour vérification. Aucune recherche n’est créée ou activée avant ton enregistrement. Choisis le français ou l’anglais dans l’application.</p><p>Ce préremplissage demandé reste local pendant au maximum une journée. La navigation privée, l’effacement des données ou un changement de navigateur ou d’appareil peuvent le perdre. Dans ce cas, copie le lien, connecte-toi, ouvre les filtres et colle-le. Vérifie la devise et les prix avant d’enregistrer.</p>'),
            ('donnees', 'Que deviennent les mots saisis ?', '<p>La génération du lien se fait dans ton navigateur. Les mots et les prix ne sont pas envoyés comme événements de mesure personnalisés. La copie utilise le presse-papiers si ton appareil le permet ; sinon le lien est sélectionné pour une copie manuelle. Ouvrir Vinted ou suivre le lien d’inscription transmet la recherche dans l’adresse de cette destination, à ta demande.</p><p>Pour calculer ton plafond d’achat, utilise le <a href="/fr/calculateur-marge-vinted">calculateur de marge</a>. Continue avec la <a href="/fr/achat-revente-vinted">méthode d’achat-revente</a>, les <a href="/fr/recherches-enregistrees-vinted">recherches sauvegardées</a> ou la <a href="/fr/alertes-vinted-telephone">configuration des alertes sur téléphone</a>.</p>'),
        ]
    return title, desc, h1, lead, sections


def phone(lang):
    if lang == 'en':
        title = 'Set Up SNYPD Vinted Alerts on iPhone and Android | SNYPD'
        desc = 'Set up new-listing alerts on your phone: iPhone Home Screen installation, Android permissions, a local device test and troubleshooting.'
        h1 = 'Get SNYPD new-listing alerts on your phone'
        lead = 'Set up a saved search, allow notifications on the device you use, then check the notification display and monitoring status separately.'
        sections = [
            ('before', 'Before you start', '<p>SNYPD is independent of Vinted. Its alerts concern new matching listings in your saved searches, not price reductions on existing listings or Vinted account messages. Sign in on this device and save your first hunt. Free starts with three days of 24/7 monitoring after the first saved search; afterwards Free monitors while the dashboard is open. Paid access keeps monitoring with the dashboard closed. Check <a href="/plans">current plans</a> and the trial status shown in your dashboard.</p>'),
            ('iphone', 'iPhone and iPad', '<ol><li>Use iOS or iPadOS 16.4 or later. Open SNYPD in Safari.</li><li>Use Share, then Add to Home Screen; keep Open as Web App enabled if shown.</li><li>Open SNYPD from that icon, sign in and save a hunt.</li><li>Tap Set up alerts or Enable alerts, then allow the notification request.</li></ol><p>iPhone web push needs the Home Screen app. If an Instagram or Facebook browser prevents installation, open the page in Safari first. If alerts are silenced, review Notifications and Focus settings for the installed app.</p>'),
            ('android', 'Android', '<ol><li>Open SNYPD in Chrome in a normal browsing session and sign in.</li><li>Save a hunt, then tap Set up alerts or Enable alerts and allow notifications.</li><li>If blocked, review Chrome’s site permissions for snypd.store and Android’s notification settings for Chrome.</li></ol><p>Chrome does not deliver site notifications in private browsing. Installation to the Home Screen is optional for this Android setup; permission is still needed.</p>'),
            ('test', 'Test this device, then check real delivery', '<p>When the dashboard shows Alerts on - turn off, press <strong>Test this device</strong>. This displays a local test through the registered service worker on your current device. It does not request a new subscription, create a listing, send another person a message or test the backend’s new-listing pipeline.</p><p>If the local test appears, the device can display notifications in that state. For real delivery, keep a hunt active, confirm monitoring is running under your plan or trial, and check a subsequent new match. In Every mode matches can notify individually; Calm mode groups matches and can wait for its configured interval. No new matching listing means there may be no alert to receive.</p>'),
            ('trouble', 'Troubleshoot one layer at a time', '<ul><li><strong>No prompt:</strong> confirm you opened the installed iPhone app or a supported Android browser, then tap the enable control directly.</li><li><strong>Blocked permission:</strong> allow this site/app in browser and OS settings, return and try again. Repeated taps cannot override a denial.</li><li><strong>Device test fails:</strong> check notification permissions, Focus or Do Not Disturb and the browser’s ability to show notifications.</li><li><strong>Device test works, but no listing alert:</strong> check active hunt filters, new matches, Calm mode, monitoring/trial status and connection. A successful local test does not prove server delivery.</li><li><strong>Server registration fails:</strong> the dashboard should offer a retry. Wait for its enabled status; do not treat browser permission alone as a registered device.</li></ul><p>Send <a href="/support">support</a> your OS/browser version, the visible status and whether the local test appeared. Do not share passwords, session tokens or push subscription URLs.</p>'),
        ]
    else:
        title = 'Configurer les alertes SNYPD sur iPhone et Android | SNYPD'
        desc = 'Configure les alertes de nouvelles annonces sur téléphone : installation iPhone, autorisations Android, test local et dépannage étape par étape.'
        h1 = 'Reçois les nouvelles annonces SNYPD sur ton téléphone'
        lead = 'Enregistre une recherche, autorise les notifications sur cet appareil, puis vérifie séparément leur affichage et l’état de la surveillance.'
        sections = [
            ('avant', 'Avant de commencer', '<p>SNYPD est indépendant de Vinted. Ses alertes concernent les nouvelles annonces de tes recherches, pas les baisses de prix d’annonces existantes ni les messages de ton compte Vinted. Connecte-toi sur cet appareil et enregistre ta première recherche. Free commence par trois jours de surveillance 24 h/24 après cette première recherche ; ensuite la surveillance gratuite fonctionne avec le tableau de bord ouvert. L’accès payant maintient la surveillance lorsque tu le fermes. Vérifie les <a href="/plans?lang=fr">offres actuelles</a> et la date d’essai affichée dans ton tableau de bord.</p>'),
            ('iphone', 'iPhone et iPad', '<ol><li>Utilise iOS ou iPadOS 16.4 minimum. Ouvre SNYPD dans Safari.</li><li>Choisis Partager puis Sur l’écran d’accueil ; garde Ouvrir comme app web activé si proposé.</li><li>Ouvre cette icône, connecte-toi et enregistre une recherche.</li><li>Touche Configurer les alertes ou Activer les alertes, puis autorise les notifications.</li></ol><p>Les notifications web iPhone nécessitent l’application de l’écran d’accueil. Si Instagram ou Facebook bloque l’installation, ouvre d’abord la page dans Safari. En cas de silence, vérifie les réglages Notifications et Concentration de l’application installée.</p>'),
            ('android', 'Android', '<ol><li>Ouvre SNYPD dans Chrome en navigation normale et connecte-toi.</li><li>Enregistre une recherche, touche Configurer les alertes ou Activer les alertes et autorise les notifications.</li><li>Si elles sont bloquées, vérifie les autorisations du site snypd.store dans Chrome et celles de Chrome dans Android.</li></ol><p>Chrome ne fournit pas les notifications de site en navigation privée. L’installation sur l’écran d’accueil est facultative pour ce parcours Android ; l’autorisation reste nécessaire.</p>'),
            ('test', 'Teste l’appareil, puis la réception réelle', '<p>Lorsque le tableau de bord indique que les alertes sont activées, touche <strong>Tester cet appareil</strong>. Ce test local utilise le service worker enregistré sur cet appareil. Il ne demande pas de nouvel abonnement, ne crée pas d’annonce, n’envoie pas de message à une autre personne et ne teste pas le parcours serveur des nouvelles annonces.</p><p>Son apparition confirme que cet appareil peut afficher une notification dans cet état. Pour une réception réelle, garde une recherche active, vérifie la surveillance prévue par ton offre ou ton essai, puis observe une nouvelle correspondance. Le mode Chaque annonce peut avertir individuellement ; le mode Calme regroupe les correspondances et peut attendre son intervalle. Sans nouvelle annonce correspondante, il peut ne rien y avoir à notifier.</p>'),
            ('depannage', 'Vérifie chaque étape séparément', '<ul><li><strong>Aucune demande :</strong> ouvre l’application installée sur iPhone ou un navigateur Android compatible, puis touche directement l’activation.</li><li><strong>Autorisation bloquée :</strong> autorise le site ou l’application dans le navigateur et le système, puis réessaie. Toucher plusieurs fois ne contourne pas un refus.</li><li><strong>Le test local échoue :</strong> vérifie les autorisations, Concentration ou Ne pas déranger et l’affichage des notifications du navigateur.</li><li><strong>Le test fonctionne, mais aucune alerte d’annonce :</strong> contrôle les filtres, nouvelles correspondances, mode Calme, surveillance, essai et connexion. Le test local ne prouve pas la réception serveur.</li><li><strong>L’enregistrement serveur échoue :</strong> réessaie depuis le tableau de bord et attends son état activé. L’autorisation du navigateur seule ne prouve pas l’enregistrement de l’appareil.</li></ul><p>Pour le <a href="/support?lang=fr">support</a>, indique le système, le navigateur, le statut affiché et le résultat du test local. Ne partage ni mot de passe, ni jeton de session, ni adresse d’abonnement push.</p>'),
        ]
    refs = [
        ('Apple: Home Screen web apps', 'https://support.apple.com/guide/iphone/turn-a-website-into-an-app-iphea86e5236/ios'),
        ('WebKit: iOS web push', 'https://webkit.org/blog/13878/web-push-for-web-apps-on-ios-and-ipados/'),
        ('Google Chrome: notifications', 'https://support.google.com/chrome/answer/3220216?co=GENIE.Platform%3DAndroid&hl=' + lang),
    ]
    text = ('Steps checked against SNYPD’s current controls and platform documentation on 2 November 2026. Labels can vary by OS version; this is setup guidance, not a claim of a completed test on every device.' if lang == 'en' else
            'Étapes vérifiées avec les commandes SNYPD actuelles et la documentation des plateformes le 2 novembre 2026. Les libellés varient selon la version ; ce guide ne prétend pas avoir testé chaque appareil.')
    sections.append(('sources', 'Sources', '<p>%s</p><ul>%s</ul>' % (text, ''.join('<li><a href="%s" rel="noopener">%s</a></li>' % (url, name) for name, url in refs))))
    return title, desc, h1, lead, sections
